const _Bowling = function Bowling(){return(
class Bowling {
  constructor() {
    this.rolls = [];
    this._frame = 1;
    this._rollInFrame = 1;
    this._pinsStanding = 10;
    this._gameOver = false;
  }

  roll(pins) {
    if (this._gameOver) throw new Error("Cannot roll after game is over");
    if (pins < 0) throw new Error("Negative roll is invalid");
    if (pins > this._pinsStanding) throw new Error("Pin count exceeds pins on the lane");

    this.rolls.push(pins);
    this._pinsStanding -= pins;

    if (this._frame < 10) {
      if (pins === 10 || this._rollInFrame === 2) {
        this._frame++;
        this._rollInFrame = 1;
        this._pinsStanding = 10;
      } else {
        this._rollInFrame = 2;
      }
    } else {
      // Frame 10 logic
      if (this._rollInFrame === 1) {
        if (pins === 10) {
          this._pinsStanding = 10;
        }
        this._rollInFrame = 2;
      } else if (this._rollInFrame === 2) {
        if (this._f10Roll1() === 10) {
          // First was strike: if second is also strike, reset pins
          this._pinsStanding = (pins === 10) ? 10 : (10 - pins);
          this._rollInFrame = 3;
        } else if (this._pinsStanding === 0) {
          // Spare: bonus roll with fresh pins
          this._pinsStanding = 10;
          this._rollInFrame = 3;
        } else {
          // Open frame in 10th: game over
          this._gameOver = true;
        }
      } else {
        // Third roll (bonus): game over
        this._gameOver = true;
      }
    }
  }

  _f10Roll1() {
    let idx = 0;
    for (let f = 0; f < 9; f++) {
      idx += (this.rolls[idx] === 10) ? 1 : 2;
    }
    return this.rolls[idx];
  }

  score() {
    if (!this._gameOver) throw new Error("Score cannot be taken until the end of the game");
    let total = 0;
    let rollIndex = 0;
    for (let frame = 0; frame < 10; frame++) {
      if (this.rolls[rollIndex] === 10) {
